"use client";
import { useState } from "react";
export default function AdminSettingsForm({ initialValues }: { initialValues: Record<string, string> }) { const [values, setValues] = useState({ maintenanceMode: initialValues.maintenanceMode || "false", supportEmail: initialValues.supportEmail || "support@civicbank.local", defaultCurrency: initialValues.defaultCurrency || "USD" }); const [notice, setNotice] = useState(""); async function save() { const response = await fetch("/api/admin/settings", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(values) }); setNotice(response.ok ? "Settings saved." : "Unable to save settings."); } return <div className="space-y-5 rounded-2xl border border-slate-800 bg-slate-900 p-6 shadow-xl"><label className="block text-xs text-slate-400">Maintenance mode<select value={values.maintenanceMode} onChange={(e) => setValues({ ...values, maintenanceMode: e.target.value })} className="mt-1.5 w-full rounded-xl border border-slate-800 bg-slate-950 px-4 py-3 text-sm text-white"><option value="false">Disabled</option><option value="true">Enabled</option></select></label><label className="block text-xs text-slate-400">Support email<input value={values.supportEmail} onChange={(e) => setValues({ ...values, supportEmail: e.target.value })} className="mt-1.5 w-full rounded-xl border border-slate-800 bg-slate-950 px-4 py-3 text-sm text-white" /></label><label className="block text-xs text-slate-400">Default currency<input value={values.defaultCurrency} onChange={(e) => setValues({ ...values, defaultCurrency: e.target.value.toUpperCase() })} className="mt-1.5 w-full rounded-xl border border-slate-800 bg-slate-950 px-4 py-3 text-sm text-white" /></label><button onClick={save} className="rounded-xl bg-red-500 px-5 py-3 text-xs font-semibold text-white">Save settings</button>{notice && <p className="text-xs text-slate-400">{notice}</p>}</div>; }